  'Deze afbeelding naar het AI-model sturen?':
      'Dieses Bild an das KI-Modell senden?',
  'De afbeelding gaat ongewijzigd naar': 'Das Bild geht unverändert an',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck schwärzt nichts in einem Bild: Gesichter, Text auf einem Bildschirmfoto und sichtbare Daten gehen mit.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Die Bildprüfung hat hier ein oder mehrere erkennbare Gesichter gefunden.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Neben dem Export werden zwei Dateien abgelegt, mit denen ein Empfänger die Schwärzungen nachprüfen kann.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'listet auf, was weggelassen wurde, ohne die Werte selbst. Diese Datei darf mit dem Bericht mitgehen.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'enthält die Schlüssel, mit denen sich jeder geschwärzte Wert zurückrechnen lässt. Senden Sie diese Datei nicht mit: damit ist die Schwärzung aufgehoben. Bewahren Sie sie bei der Quelle auf.',
  'slides': 'Folien',
  'Achtergehouden': 'Zurückgehalten',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Zurückgehalten: strenger klassifiziert als die Präsentation',
  '1 slide achtergehouden door haar TLP':
      '1 Folie durch ihr TLP zurückgehalten',
  'slides achtergehouden door hun TLP': 'Folien durch ihr TLP zurückgehalten',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Diese Folien entfallen beim Präsentieren, Exportieren und im Paket. Erhöhen Sie unter Präsentationsinfo die TLP-Stufe der Präsentation, um sie mitzunehmen.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alle Folien sind durch ihre TLP-Klassifizierung zurückgehalten — nichts anzuzeigen.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alle Folien sind durch ihre TLP-Klassifizierung zurückgehalten — nichts zu exportieren.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alle Folien sind übersprungen oder durch ihre TLP-Klassifizierung zurückgehalten — nichts anzuzeigen.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alle Folien sind übersprungen oder durch ihre TLP-Klassifizierung zurückgehalten — nichts zu exportieren.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Diagrammzahlen wurden nicht gespeichert — sie stehen nur noch in diesem Fenster:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Im Browser gibt es keine Absturzwiederherstellung: Schließen Sie diesen Tab, ist nicht gespeicherte Arbeit weg. Speichern Sie Ihre Präsentation selbst.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Die lokale CVE-Datenbank (den Download starten Sie selbst): OciDeck holt die Massendaten über api.github.com und die Release-Datei, auf die diese Adresse verweist.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE-Suche (standardmäßig aus): Ist sie eingeschaltet, geht Ihr Suchbegriff an den eingestellten CVE-Spiegel und, wenn dieser nichts findet, an die europäische Datenbank der ENISA und an MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Ein eingebettetes YouTube- oder Vimeo-Video lädt den Player bei diesem Dienst.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Im Browser: Weigert sich der Browser, eine Adresse direkt abzurufen, versucht OciDeck es über den Server, von dem die App stammt; diese Adresse erreicht dann jenen Server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Der Widerruf wurde nicht gespeichert. Beim nächsten Start gilt Ihre Einwilligung wieder.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Eine Zwischenüberschrift, die einen neuen Teil der Präsentation ankündigt. Halte sie kurz. Füge über die Bildbibliothek ein Hintergrundbild hinzu.',
  'Bronnen doorzoeken…': 'Quellen werden durchsucht…',
  'Niet doorzocht': 'Nicht durchsucht',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Diese Prüfung läuft in der Webversion nicht: Gesichtserkennung braucht eine Systembibliothek, die der Browser nicht hat. Nutze die Desktop-Version, um Bilder auf Gesichter zu prüfen.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Das Token braucht Lese- und Schreibrechte für das Repository. Gitea und Forgejo haben keine serverseitige Suche; OciDeck sucht lokal.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Das Token braucht den repo-Scope (oder feingranular: Contents lesen und schreiben).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Das Token braucht read_repository, write_repository und read_api. Die serverseitige Suche erfordert Advanced oder Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Schnelle serverseitige Suche — durch Indexierungsverzögerung kann ein gerade geändertes Deck fehlen.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Medien bleiben in einer reinen .md-Datei nicht erhalten',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Bilder, Video und Audio, die du in diesem Tab gewählt hast, liegen nur im Arbeitsspeicher. Eine reine .md-Datei bewahrt sie nicht — beim erneuten Öffnen sind sie weg. Exportiere als .ocideck-Paket, um die Medien mitzunehmen.',
