  'Vertrouwen': 'Vertrauen',
  'Certificaat bekijken': 'Zertifikat ansehen',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Die Orte, an denen du deine Präsentationen aufbewahrst und durchsuchst — Ordner auf diesem Computer, WebDAV-Server, S3-Buckets und git-Repositories durcheinander. Zieh sie in die Reihenfolge, die du willst: das oberste einer Art gilt als Standard.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-Speicher: Wenn du dich mit einem Bucket verbindest, werden der Endpunkt, der Bucket-Name und dein Zugriffsschlüssel gespeichert (der geheime Schlüssel sicher im Schlüsselbund deines Systems) und die Präsentationen, die du öffnest oder speicherst, werden an diesen Speicherdienst gesendet.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-Speicher: Wenn du dich mit einem Repository verbindest, wird dein Zugriffstoken gespeichert (sicher im Schlüsselbund deines Systems) und die Präsentationen, die du speicherst, werden als Commits an diesen Server gesendet. Eine Arbeitskopie des Repositorys bleibt unverschlüsselt auf diesem Gerät.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Für die Sprache dieser Präsentation fehlen die Krankheitsbezeichnungen. Religion, politische Meinung und Gewerkschaftsbegriffe werden erkannt, und Prüfziffernmuster (Steuer-ID, IBAN, Pass) funktionieren immer — aber verlassen Sie sich nicht darauf, dass eine Diagnose gefunden wird.',
  'niet getest': 'nicht getestet',
  'Werkte op': 'Funktionierte am',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Du bist angemeldet, hast hier aber keinen Zugriff. Dein Passwort ist nicht das Problem — bitte den Administrator um Rechte für diesen Ordner.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Dein Token ist gültig, darf das aber nicht. Gib ihm mehr Rechte, oder warte, wenn die Forge ein Limit setzt.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Das Token ist gültig, darf das aber nicht — gib ihm mehr Rechte am Repository.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Angemeldet, aber kein Zugriff — dein Passwort ist nicht das Problem. Bitte um Rechte für diesen Ordner.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Das sieht nach einer vollständigen DAV-URL aus. Bei Nextcloud leitet OciDeck diesen Pfad selbst ab — hier gehört nur der Server hin.',
  'Overnemen': 'Übernehmen',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV ist nicht (richtig) eingerichtet — prüfe die Serverdaten unter Einstellungen → Speicher.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Das git-Repository ist nicht (richtig) eingerichtet — prüfe Server, Eigentümer und Repository unter Einstellungen → Speicher.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Der Servername der Forge existiert nicht oder ist nicht auflösbar. Prüfe die Server-URL auf einen Tippfehler.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Diese Forge hat eine private oder LAN-Adresse. Markiere sie unter Einstellungen → Speicher als vertrauenswürdig intern.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Die Forge ist nicht erreichbar — prüfe deine Verbindung und die Server-URL.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Anmeldung bei der Forge fehlgeschlagen. Prüfe dein Token: Es braucht Lesezugriff auf das Repository und Schreibzugriff zum Speichern.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Nicht im Repository gefunden — oder dein Token darf es nicht sehen.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Die Forge hat einen Fehler gemeldet. Versuche es später erneut.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Diese Adresse antwortet nicht wie eine Forge. Stimmt die Forge-Art unter Einstellungen → Speicher?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Richte zuerst einen WebDAV-Server unter Einstellungen → Speicher ein.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Nötig, wenn die Forge in einem privaten oder Heimnetzwerk läuft. Ohne dieses Häkchen weist die Sicherheitsprüfung eine private Adresse ab.',
